float pll(float input)
{
	//return input;
    float buffer;
    static float last_value = 0;
    float buffer_real = input * lut_cos_6[lut_ptr_6];           //Modulieren (Realteil!)
    float buffer_imag = input * lut_sin_6[lut_ptr_6];           //Modulieren (Imaginärteil!)
    lut_ptr_6 = (lut_ptr_6 + 1) % 6;                            //Pointer (Indizierer) hochzählen und bei bedarf zurücketzen
    buffer_real = conv_fir_2k_real(buffer_real);                //Hier werden zwei Funktionen (wenigstens zwei Circulare Buffer - Real und Imag) benötigt
    buffer_imag = conv_fir_2k_imag(buffer_imag);

    //sieht oke
    /*buffer = abs(buffer_real, buffer_imag);
	buffer_real = buffer * lut_cos_48[lut_ptr_48];      //Eine Mul. öangt, da buffer ein reelles Signal ist
	buffer_imag = buffer * -lut_sin_48[lut_ptr_48];     //Sollte gehen, da der Sinus Punktsymmetrisch ist! -normal ist die Freq. negativ, nicht der ganze Term
	buffer_real = conv_fir_200_real(buffer_real);
	buffer_imag = conv_fir_200_imag(buffer_imag);
	buffer_real = buffer_real * lut_cos_48[lut_ptr_48] - buffer_imag * lut_sin_48[lut_ptr_48];
	lut_ptr_48 = (lut_ptr_48 + 1) % 48;
	return buffer_real;*/


    if (pointer_down_sample == 0)                                   //Alle vier Aufrufe ausführen (Berechnungen für downgesampelte Daten) - funktioniert
    {
        //Mit down_sample[0] weiterrechnen - anderen 3 Werte wegwerfen!
        //Eventuell alles hier Reell - damit wär Rechendauer ca. halb so lang!
        //Geht auch ab hier mit reeller Modulation (siehe Matlab) - doch nicht - in Matlab mit fs verschoben anstatt fest mit 1k Hz
        //Passt doch nicht mit Realteilbildung, da sich das Spektrum überlagert - in Matlab haben wir um fs verschoben, daher was das unproblematisch in Matlab! Hier verschieben wir fest um 1k Hz
        //In Doku erwähnen, dass wir nur real modulieren wollten
        buffer = abs(buffer_real, buffer_imag);
        buffer_real = buffer * lut_cos_48[lut_ptr_48];      //Eine Mul. öangt, da buffer ein reelles Signal ist
        buffer_imag = buffer * -lut_sin_48[lut_ptr_48];     //Sollte gehen, da der Sinus Punktsymmetrisch ist! -normal ist die Freq. negativ, nicht der ganze Term
        buffer_real = conv_fir_200_real(buffer_real);
        buffer_imag = conv_fir_200_imag(buffer_imag);
        //(a+jb)*(c+jd) = ac-bd + j(ad+bc)
        buffer = buffer_real * lut_cos_48[lut_ptr_48] - buffer_imag * lut_sin_48[lut_ptr_48];
        //buffer_imag = buffer_imag * lut_cos_48[lut_ptr_48] + buffer_real * lut_sin_48[lut_ptr_48];  //Wird Wahrscheinlich nicht benötigt
        lut_ptr_48 = (lut_ptr_48 + 4) % 48;
        //buffer = conv_fir_upsample(buffer);

        //Nur zum Oszi bild anschauen
        input_pll = buffer;
        //Erst PLL, dann Upsamplen
        lut_ptr_pll = (int)((lut_ptr_pll + lut_pll_step) - (100 * phi));// % 12000;

        if(lut_ptr_pll > 6000)
        {
        	lut_ptr_pll = lut_ptr_pll - 6000;
        	if (inSecondHalf)
        	{
        		inSecondHalf = 0;
        	}
        	else
        	{
        		inSecondHalf = 1;
        	}
        }
		if (last_value <= 0 && buffer > 0)
		{
			if(inSecondHalf)
			{
				phi = -lut_sin_6k[lut_ptr_pll];
			}
			else
			{
				phi = lut_sin_6k[lut_ptr_pll];
			}
		}
        last_value = buffer;
        //Upsampling Filter den Wert übergeben!
        if(inSecondHalf)
        {
        	buffer = conv_fir_upsample(-lut_sin_6k[lut_ptr_pll] * 25000.0);
        }
        else
        {
        	buffer = conv_fir_upsample(lut_sin_6k[lut_ptr_pll] * 25000.0);
        }
    }
    else
    {
        //Upsampling Filter eine 0 übergeben!
        buffer = conv_fir_upsample(0);
    }
    pointer_down_sample = (pointer_down_sample + 1) % down_len;     //Pointer inkrementieren - Wertebereich [0:3]
    return buffer;//lut_sin_6k[3000] * 5000.0;//test;//buffer;
}


float abs(float real, float imag)
{
    return ((real*real) + (imag*imag)) / 1024;
}

float conv_fir_2k_real(float new_sample)
{
    circular_buffer_2k_real[pointer_2k_real] = new_sample;
    pointer_2k_real = (pointer_2k_real + 1) % len2k;
    int diff = len2k - pointer_2k_real;
    float y = 0;
    for (int i = pointer_2k_real; i < len2k; i++)
    {
        y += (fir_2k[i - pointer_2k_real] * circular_buffer_2k_real[i]);
    }
    for (int i = 0; i < pointer_2k_real; i++)
    {
        y += (fir_2k[i + diff] * circular_buffer_2k_real[i]);
    }
    return y;
}

float conv_fir_2k_imag(float new_sample)
{
    circular_buffer_2k_imag[pointer_2k_imag] = new_sample;
    pointer_2k_imag = (pointer_2k_imag + 1) % len2k;
    int diff = len2k - pointer_2k_imag;
    float y = 0;
    for (int i = pointer_2k_imag; i < len2k; i++)
    {
        y += (fir_2k[i - pointer_2k_imag] * circular_buffer_2k_imag[i]);
    }
    for (int i = 0; i < pointer_2k_imag; i++)
    {
        y += (fir_2k[i + diff] * circular_buffer_2k_imag[i]);
    }
    return y;
}

