float conv_fir_upsample(float new_sample)
{
    circular_buffer_upsample[pointer_upsample] = new_sample;
    pointer_upsample = (pointer_upsample + 1) % lenupsample;
    int diff = lenupsample - pointer_upsample;
    float y = 0;
    for (int i = pointer_upsample; i < lenupsample; i++)
    {
        y += (fir_upsample[i - pointer_upsample] * circular_buffer_upsample[i]);
    }
    for (int i = 0; i < pointer_upsample; i++)
    {
        y += (fir_upsample[i + diff] * circular_buffer_upsample[i]);
    }
    return y;
}

